const payload = $input.first().json.body || $input.first().json;
const alerts = payload.alerts || [];
const out = [];
for (const a of alerts) {
  const L = a.labels || {};
  out.push({ json: {
    route: a.status === 'resolved' ? 'resolved' : 'firing',
    alertname: L.alertname || 'Unknown',
    severity: L.severity || 'warning',
    namespace: L.namespace || '',
    kind: L.kind || '',
    name: L.name || '',
    heal_strategy: L.heal_strategy || 'none',
    summary: (a.annotations && a.annotations.summary) || '',
    description: (a.annotations && a.annotations.description) || '',
    startsAt: a.startsAt || '',
    fingerprint: a.fingerprint || ''
  }});
}
if (!out.length) throw new Error('webhook 载荷中无告警');
return out;
